from logging import getLogger

from .bts.bts_classical import BtsClassical
from .exceptions import InvalidBtsType


class BtsFactory(object):

    _bts_apis = {'ClassicalBts': BtsClassical,
                 'default': BtsClassical}

    @classmethod
    def get_bts(cls, bts_config, alias):
        """
        Creates new BTS based on given config and with given alias.

        :param bts_config: configuration object of BTS to which requests for current statuses will be send;
                           should contain all data required to connect to given BTS;
                           if None will be provided then default connection data will be used
        :type bts_config: taf.config.testline.gnb.gnb.gNB or None
        :param alias: connection alias which will be used during creation of BTS connection
        :type alias: str
        :return: BTS instance of appropriate type
        :rtype: Bts
        :raises InvalidBtsType: when requested BTS type from BTS config is unsupported
        """
        logger = getLogger()
        logger.debug("Creating BTS with '{}' alias".format(alias))
        bts_api = cls._get_bts_api(bts_config)
        logger.debug("Selected BTS API: {}".format(bts_api))
        return bts_api(config=bts_config, alias=alias)

    @classmethod
    def _get_bts_api(cls, bts_config):
        bts_type = cls._get_bts_type(bts_config)
        bts_api = cls._bts_apis.get(bts_type, None)
        cls._check_bts_api(bts_api, bts_type)
        return bts_api

    @classmethod
    def _get_bts_type(cls, bts_config):
        if bts_config is None:
            return 'default'
        return bts_config.__class__.__name__

    @staticmethod
    def _check_bts_api(bts_api, bts_type):
        if bts_api is None:
            raise InvalidBtsType('Invalid BTS type provided: {}'.format(bts_type))
